// RM0008 / RM0368 / RM0383 SPI1: bounded 8/16-bit, MSB/LSB-first, modes 0..3 master.
// Every edge reaches the electrical circuit. No direct sensor/controller access.
export class STMSPI1 {
 constructor(runtime){this.r=runtime;this.base=0x40013000;this.regs=new Map([[0,0],[4,0],[16,7],[20,0],[24,0],[28,0],[32,2]]);this.sr=2;this.dr=0;this.tdr=null;this.shift=null;this.next=Infinity;this.sck=false;this.mosi=false;this.drRead=false;}
 clocked(){return !!(this.r.regs.get(this.r.board.cpu==='cortex-m4f'?0x40023844:0x40021018)&(1<<12));}
 enabled(){return this.clocked()&&!!(this.regs.get(0)&64);}
 divider(){const f4=this.r.board.cpu==='cortex-m4f',cf=this.r.regs.get(f4?0x40023808:0x40021004)||0,n=(cf>>>(f4?13:11))&7;return (n<4?1:1<<(n-3))*(2<<((this.regs.get(0)>>>3)&7))*(this.r.system?.factor()??1);}
 mapped(pin,input=false){if(!pin||!this.r.board.gpio.includes(pin))return false;const f4=this.r.board.cpu==='cortex-m4f',n=+pin.slice(2),bank=pin.charCodeAt(1)-65;if(f4){const base=0x40020000+bank*1024;return !!(this.r.regs.get(0x40023830)&(1<<bank))&&((this.r.regs.get(base)>>>n*2)&3)===2&&((this.r.regs.get(base+32+(n>=8?4:0))>>>((n%8)*4))&15)===5&&!(this.r.regs.get(base+4)&(1<<n));}const c=(this.r.regs.get(0x40010800)>>>n*4)&15;return bank===0&&!(this.r.regs.get(0x40010004)&1)&&!!(this.r.regs.get(0x40021018)&4)&&(input?!(c&3)&&[1,2].includes(c>>>2):!!(c&3)&&(c>>>2)===2);}
 pins(){const f4=this.r.board.cpu==='cortex-m4f';return {sck:['PA5',...(f4?['PB3']:[])].find(p=>this.mapped(p)),miso:['PA6',...(f4?['PB4']:[])].find(p=>this.mapped(p,true)),mosi:['PA7',...(f4?['PB5']:[])].find(p=>this.mapped(p))};}
 refresh(){this.r.circuit?.refresh(true);}
 format(){const cr=this.regs.get(0)||0;return {bits:cr&2048?16:8,lsb:!!(cr&128),cpol:!!(cr&2),cpha:!!(cr&1)};}
 bit(s,index){return !!(s.value&(1<<(s.lsb?index:s.bits-1-index)));}
 pump(){if(this.shift||this.tdr===null||!this.enabled())return;this.shift={value:this.tdr,rx:0,edge:0,...this.format(),half:this.divider()/2};this.tdr=null;this.sr|=2|128;this.sck=this.shift.cpol;if(!this.shift.cpha)this.mosi=this.bit(this.shift,0);this.next=this.r.count+this.shift.half;this.refresh();}
 tick(){if(!this.enabled()){if(this.shift||this.tdr!==null){this.shift=null;this.tdr=null;this.next=Infinity;this.sr=(this.sr&~128)|2;this.sck=!!(this.regs.get(0)&2);this.refresh();}return;}while(this.shift&&this.next<=this.r.count){const s=this.shift,edge=s.edge++,at=this.next,leading=!(edge&1),index=Math.floor(edge/2);this.sck=leading?!s.cpol:s.cpol;if(s.cpha?leading:!leading&&index+1<s.bits)this.mosi=this.bit(s,s.cpha?index:index+1);this.refresh();if(s.cpha?!leading:leading){let high;if(this.r.circuit){const v=this.r.inputVoltages[this.pins().miso];if(!Number.isFinite(v)||v>.99&&v<2.31)throw Error('SPI1 MISO hattı boşta veya mantık seviyesi belirsiz; kablo ve beslemeyi kontrol edin.');high=v>=2.31;}else high=!!this.r.inputs[this.pins().miso];if(high)s.rx|=1<<(s.lsb?index:s.bits-1-index);}if(edge===s.bits*2-1){if(this.sr&1)this.sr|=64;else{this.dr=s.rx&(s.bits===16?65535:255);this.sr|=1;}this.shift=null;this.sr&=~128;this.next=Infinity;this.pump();}else this.next=at+s.half;}}
 read(a,n){const off=(a&~3)-this.base;if(off<0||off>32)return undefined;if(![0,4,8,12,16,20,24,28,32].includes(off))throw Error('SPI1 register desteklenmiyor.');let v=off===8?this.sr:off===12?this.dr:this.regs.get(off)||0;if(off===12){this.sr&=~1;this.drRead=true;}if(off===8&&this.drRead){this.sr&=~64;this.drRead=false;}return n===4?v>>>0:(v>>>((a&3)*8))&(n===1?255:65535);}
 write(a,v,n){const off=(a&~3)-this.base;if(off<0||off>32)return false;if(![0,4,8,12,16,20,24,28,32].includes(off))throw Error('SPI1 register desteklenmiyor.');if(off===12){if(this.enabled()){if(this.tdr!==null)throw Error('SPI1 TXE beklenmeli: DR dolu.');this.tdr=v&(this.format().bits===16?65535:255);this.sr&=~2;this.pump();}return true;}if(off===8)return true;if(n!==4){const shift=(a&3)*8,mask=(n===1?255:65535)<<shift;v=((this.regs.get(off)||0)&~mask)|((v<<shift)&mask);}if(off===0&&this.shift&&((v^(this.regs.get(0)||0))&~64))throw Error("SPI1 BSY sırasında ayar değişimi desteklenmiyor; transferi bitirin.");if(off===0&&(this.regs.get(0)&64)&&(v&64)&&((v^this.regs.get(0))&(3|128|2048)))throw Error('SPI1 format değişimi SPE=0 gerektirir.');if(off===0&&v&64){if((v&~(64|4|256|512|56|3|128|2048))||!(v&4))throw Error('SPI1 yalnız 8/16-bit mode 0..3 master destekler.');if(v&512){if(!(v&256))throw Error('SPI1 yazılım NSS için SSI=1 gerekli.');}else if(!(this.regs.get(4)&4)||!this.mapped('PA4'))throw Error('SPI1 hardware NSS için SSOE ve PA4 AF gerekli; NSS giriş/multimaster desteklenmez.');if(Object.values(this.pins()).some(p=>!p))throw Error('SPI1 SCK/MISO/MOSI GPIO AF ayarı eksik.');}if(off===4&&v&~231)throw Error('SPI1 TI modu henüz desteklenmiyor.');if(off===4&&this.enabled()&&!(this.regs.get(0)&512)&&!(v&4))throw Error('SPI1 SSOE değişimi için SPE=0 gerekli.');if(off===28&&v&2048)throw Error('SPI1 I²S modu henüz desteklenmiyor.');this.regs.set(off,v>>>0);if(off===0&&!this.shift)this.sck=!!(v&2);this.tick();this.refresh();return true;}
 irq(){const cr=this.regs.get(4);return this.enabled()&&!!((cr&64)&&(this.sr&1)||(cr&128)&&(this.sr&2)||(cr&32)&&(this.sr&64));}
 outputs(states){const pins=this.pins();if(this.enabled()&&!(this.regs.get(0)&512)&&(this.regs.get(4)&4)&&this.mapped('PA4'))states.PA4={high:false,outputEnabled:true,voltage:0,mode:'SPI1_NSS'};if(this.enabled())for(const [kind,high]of [['sck',this.sck],['mosi',this.mosi]]){const p=pins[kind];if(p)states[p]={high,outputEnabled:true,voltage:high?3.3:0,mode:'SPI1_'+kind.toUpperCase()};}if(this.enabled()&&pins.miso){const p=pins.miso,n=+p.slice(2),bank=p.charCodeAt(1)-65,f4=this.r.board.cpu==='cortex-m4f',pull=f4?(this.r.regs.get(0x4002000c+bank*1024)>>>n*2)&3:((this.r.regs.get(0x40010800)>>>24)&15)===8?(this.r.regs.get(0x4001080c)&64?1:2):0;states[p].mode=pull===1?'INPUT_PULLUP':pull===2?'INPUT_PULLDOWN':'INPUT';}return states;}
}
